package br.com.onda;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.Build;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;
/** All discovery controls scroll on short screens; Close is always outside the list. */
final class MenuPanel {
 static int[] shortcuts(Context c,String key,String[] descriptions){String saved=c.getSharedPreferences("menu_shortcuts",0).getString(key,null);ArrayList<Integer> indices=new ArrayList<>();if(saved!=null){try{JSONArray a=new JSONArray(saved);for(int n=0;n<a.length()&&indices.size()<3;n++)for(int i=0;i<descriptions.length;i++)if(descriptions[i].equals(a.optString(n))&&!indices.contains(i)){indices.add(i);break;}}catch(JSONException ignored){}}else{String[] defaults=key.equals("Menu de vídeos")?new String[]{"Abrir arquivo de vídeo","Legendas do vídeo","Fones e Bluetooth"}:new String[]{"Downloads","Playlists","Estúdio de som"};for(String value:defaults)for(int i=0;i<descriptions.length;i++)if(value.equals(descriptions[i]))indices.add(i);}int[] result=new int[indices.size()];for(int i=0;i<result.length;i++)result[i]=indices.get(i);return result;}
 static void save(Context c,String key,String[] descriptions,boolean[] selected){JSONArray a=new JSONArray();for(int i=0;i<descriptions.length&&a.length()<3;i++)if(selected[i])a.put(descriptions[i]);c.getSharedPreferences("menu_shortcuts",0).edit().putString(key,a.toString()).apply();}
 static Dialog show(Activity a,View anchor,String[] labels,String[] descriptions,Runnable[] actions){
  if(labels.length!=descriptions.length||labels.length!=actions.length)throw new IllegalArgumentException("Menu arrays differ");Dialog dialog=new Dialog(a);dialog.requestWindowFeature(Window.FEATURE_NO_TITLE);String key=anchor.getContentDescription()==null?"Menu":anchor.getContentDescription().toString();LinearLayout panel=column(a);panel.setFocusableInTouchMode(true);panel.setPadding(Ui.dp(a,8),Ui.dp(a,4),Ui.dp(a,8),Ui.dp(a,4));TextView title=Ui.text(a,key,16,Ui.CYAN);Ui.bold(title);title.setPadding(Ui.dp(a,12),Ui.dp(a,8),Ui.dp(a,12),Ui.dp(a,8));if(Build.VERSION.SDK_INT>=28)title.setAccessibilityHeading(true);panel.addView(title);
  ScrollView scroll=new ScrollView(a);scroll.setContentDescription("Opções do menu");scroll.setVerticalScrollBarEnabled(true);scroll.setScrollbarFadingEnabled(false);LinearLayout options=column(a);scroll.addView(options);panel.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));
  EditText search=new EditText(a);Ui.input(search);search.setHint("Buscar no menu");search.setContentDescription("Buscar no menu");options.addView(search,new LinearLayout.LayoutParams(-1,-2));Spinner categories=new Spinner(a);categories.setContentDescription("Categoria do menu");categories.setAdapter(new ArrayAdapter<>(a,android.R.layout.simple_spinner_dropdown_item,MenuCatalog.GROUPS));Ui.spinner(categories);options.addView(categories,new LinearLayout.LayoutParams(-1,-2));
  LinearLayout shortcuts=column(a);options.addView(shortcuts);Runnable[] rebuild={null};rebuild[0]=()->{shortcuts.removeAllViews();LinearLayout heading=new LinearLayout(a);heading.setGravity(Gravity.CENTER_VERTICAL);heading.addView(Ui.text(a,"Atalhos",13,Ui.CYAN),new LinearLayout.LayoutParams(0,-2,1));Button edit=Ui.button(a,"Editar",v->edit(a,dialog,key,labels,descriptions,rebuild[0]));edit.setContentDescription("Editar atalhos do menu");Ui.ghost(edit);heading.addView(edit);shortcuts.addView(heading);LinearLayout row=new LinearLayout(a);for(int index:shortcuts(a,key,descriptions)){Button b=Ui.button(a,MenuCatalog.shortName(labels[index]),v->{dialog.dismiss();actions[index].run();});b.setContentDescription("Atalho: "+descriptions[index]);row.addView(b,new LinearLayout.LayoutParams(0,-2,1));}shortcuts.addView(row);};rebuild[0].run();
  TextView status=Ui.text(a,"",12,Ui.MUTED);status.setPadding(Ui.dp(a,12),Ui.dp(a,8),Ui.dp(a,12),Ui.dp(a,8));status.setContentDescription("Resultados do menu");options.addView(status);ArrayList<View> rows=new ArrayList<>();for(int i=0;i<labels.length;i++){final int index=i;TextView row=Ui.text(a,labels[i],16,Ui.TEXT);row.setContentDescription(descriptions[i]);row.setMinHeight(Ui.dp(a,48));row.setGravity(Gravity.CENTER_VERTICAL);row.setPadding(Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12),Ui.dp(a,12));row.setBackground(Ui.ripple(a,Ui.shape(a,Color.TRANSPARENT,0,10),10));row.setFocusable(true);row.setOnClickListener(v->{dialog.dismiss();actions[index].run();});rows.add(row);options.addView(row,new LinearLayout.LayoutParams(-1,-2));}
  Runnable filter=()->{int count=0;for(int i=0;i<rows.size();i++){boolean visible=MenuCatalog.matches(labels[i],descriptions[i],search.getText().toString(),Math.max(0,categories.getSelectedItemPosition()));rows.get(i).setVisibility(visible?View.VISIBLE:View.GONE);if(visible)count++;}status.setText(count==0?"Nenhuma opção encontrada. Tente outra busca ou categoria.":count+" opções");};search.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int co,int af){}public void onTextChanged(CharSequence s,int st,int before,int co){filter.run();}public void afterTextChanged(android.text.Editable e){}});categories.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int at,long id){filter.run();}});filter.run();
  Button close=Ui.button(a,"Fechar",v->dialog.dismiss());close.setId(android.R.id.button2);Ui.ghost(close);panel.addView(close,new LinearLayout.LayoutParams(-1,-2));Rect frame=new Rect();a.getWindow().getDecorView().getWindowVisibleDisplayFrame(frame);if(frame.isEmpty()){Point p=new Point();a.getWindowManager().getDefaultDisplay().getSize(p);frame.set(0,0,p.x,p.y);}int width=Math.max(1,Math.min(Ui.dp(a,480),frame.width()-Ui.dp(a,16)));int desired=Ui.dp(a,8);for(View v:new View[]{title,options,close}){v.measure(View.MeasureSpec.makeMeasureSpec(Math.max(1,width-Ui.dp(a,16)),View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(0,View.MeasureSpec.UNSPECIFIED));desired+=v.getMeasuredHeight();}dialog.setContentView(panel);dialog.show();panel.requestFocus();Window w=dialog.getWindow();if(w!=null){w.setBackgroundDrawable(Ui.shape(a,Ui.SURFACE,Ui.BORDER,20));w.setSoftInputMode(WindowManager.LayoutParams.SOFT_INPUT_ADJUST_RESIZE|WindowManager.LayoutParams.SOFT_INPUT_STATE_ALWAYS_HIDDEN);w.setLayout(width,Math.max(1,Math.min(desired,Math.min(Ui.dp(a,600),frame.height()-Ui.dp(a,16)))));}return dialog;
 }
 private static LinearLayout column(Context c){LinearLayout l=new LinearLayout(c);l.setOrientation(LinearLayout.VERTICAL);return l;}
 private static void edit(Activity a,Dialog parent,String key,String[] labels,String[] descriptions,Runnable changed){boolean[] selected=new boolean[labels.length];for(int i:shortcuts(a,key,descriptions))selected[i]=true;new AlertDialog.Builder(a).setTitle("Escolha até 3 atalhos").setMultiChoiceItems(labels,selected,(d,which,on)->{selected[which]=on;int count=0;for(boolean b:selected)if(b)count++;if(on&&count>3){selected[which]=false;((AlertDialog)d).getListView().setItemChecked(which,false);Toast.makeText(a,"Desmarque um atalho para escolher outro.",Toast.LENGTH_SHORT).show();}}).setPositiveButton("Salvar",(d,w)->{save(a,key,descriptions,selected);if(parent.isShowing())changed.run();}).setNegativeButton("Cancelar",null).setNeutralButton("Restaurar",(d,w)->{a.getSharedPreferences("menu_shortcuts",0).edit().remove(key).apply();if(parent.isShowing())changed.run();}).show();}
}
